unsafe extern "C" fn vt_gnoblin_std_layout_vtable_find_split(
    user: *mut c_void,
    client: u64,
    x: f64,
    y: f64,
    out: *mut GnoblinStdSplit,
) -> i32 {
    let code = contain(|| {
        // SAFETY: `user` is the object the arena made for this registration, which the library has not dropped yet.
        let object = unsafe { user_of(user) };
        let mut args: Vec<Dyn> = Vec::new();
        args.push(Dyn::Uint(client));
        args.push(Dyn::Float(x));
        args.push(Dyn::Float(y));
        let result = object.invoke_method("find_split", args);
        match result {
            Ok(Dyn::Nil) => 0,
            Ok(item) => {
                let mut arena = Arena::new();
                match write_gnoblin_std_split(&mut arena, &item, "GnoblinStdSplit") {
                    // SAFETY: the library passes a record it owns for this call.
                    Ok(filled) => {
                        unsafe { *out = filled };
                        1
                    }
                    Err(_) => E_TYPE,
                }
            }
            Err(_) => E_PANIC,
        }
    });
    code
}

